def decode_cow(text):
    # COW language: Capital 'M' = 1, lowercase 'm' = 0, 'O'/'o' are separators
    try:
        binary = ""
        for char in text:
            if char == 'M':
                binary += '1'
            elif char == 'm':
                binary += '0'

        # Convert binary to ASCII
        result = ""
        for i in range(0, len(binary), 8):
            if i + 8 <= len(binary):
                byte = binary[i:i+8]
                result += chr(int(byte, 2))
        return result
    except Exception as e:
        return f"Error decoding cow: {e}"

