import re

# COW language interpreter
# Based on https://esolangs.org/wiki/COW
def decode_cow(program):
    cow_commands = {
        'moo': '+', 'mOo': '-', 'moO': '>', 'mOO': '<',
        'Moo': '.', 'MOo': ',', 'MOO': '[', 'moo': ']',
        'OOO': '0', 'MMM': '1', 'OOM': '2', 'oom': '3'
    }

    # Extract commands from the program
    commands = []
    i = 0
    while i < len(program):
        found = False
        for cmd, val in cow_commands.items():
            if program[i:i+len(cmd)] == cmd:
                commands.append(val)
                i += len(cmd)
                found = True
                break
        if not found:
            i += 1

    return ''.join(commands)

def decode_pig(program):
    # Ook-like language where OINK and oink are used
    pig_commands = {
        'OINK': '+', 'oink': '-', 'Oink': '>', 'oInk': '<',
        'OInk': '.', 'OiNk': ',', 'OINk': '[', 'oiNK': ']'
    }

    # Extract commands from the program
    commands = []
    for match in re.finditer(r'OINK|oink|Oink|oInk|OInk|OiNk|OINk|oiNK', program, re.IGNORECASE):
        cmd = match.group(0)
        if cmd in pig_commands:
            commands.append(pig_commands[cmd])

    return ''.join(commands)

def decode_rooster(program):
    # Cockoo-like language
    rooster_commands = {
        'kikiriki': '+', 'kikirikI': '-', 'kikiriKi': '>', 'kikiriKI': '<',
        'Kikiriki': '.', 'KikirikI': ',', 'KikiriKi': '[', 'KikiriKI': ']'
    }

    # Extract commands from the program
    commands = []
    i = 0
    while i < len(program):
        found = False
        for cmd, val in rooster_commands.items():
            if program[i:i+len(cmd)] == cmd:
                commands.append(val)
                i += len(cmd)
                found = True
                break
        if not found:
            i += 1

    return ''.join(commands)

