    # Sheep-like language
    sheep_commands = {
        'baaaa': '+', 'baaAa': '-', 'baaAA': '>', 'baAAa': '<',
        'baAAA': '.', 'bAAAA': ',', 'Baaaa': '[', 'BaaaA': ']'
