#!/usr/bin/env python3

import sys
import re

def cow_to_bf(code):
    """Convert COW to Brainfuck"""
    # Dictionary to translate COW to Brainfuck
    translation = {
        'MOO': '>', 'MoO': '<', 'MOo': '+', 'MoO': '-',
        'mOO': '.', 'mOo': ',', 'moO': '[', 'moo': ']'
    }

    # Split by patterns
    code_fragments = []
    i = 0
    while i < len(code):
        for pattern in translation:
            if code[i:i+len(pattern)] == pattern:
                code_fragments.append(pattern)
                i += len(pattern)
                break
        else:
            i += 1

    # Convert to Brainfuck
    bf_code = ''.join(translation.get(fragment, '') for fragment in code_fragments)
    return bf_code

def sheep_to_bf(code):
    """Convert Sheep to Brainfuck"""
    # Dictionary for Sheep language
    translation = {
        'baa': '+', 'baA': '-', 'bAa': '>', 'bAA': '<',
        'Baa': '.', 'BaA': ',', 'BAa': '[', 'BAA': ']'
    }

    # Split by patterns
    code_fragments = []
    i = 0
    while i < len(code):
        matched = False
        for pattern in translation:
            if i + len(pattern) <= len(code) and code[i:i+len(pattern)] == pattern:
                code_fragments.append(pattern)
                i += len(pattern)
                matched = True
                break
        if not matched:
            i += 1

    # Convert to Brainfuck
    bf_code = ''.join(translation.get(fragment, '') for fragment in code_fragments)
    return bf_code

def pig_to_bf(code):
    """Convert Pig to Brainfuck"""
    # Dictionary for Pig language
    translation = {
        'oink': '+', 'oinK': '-', 'Oink': '>', 'OinK': '<',
        'oiNk': '.', 'oiNK': ',', 'OiNk': '[', 'OiNK': ']'
    }

    # Split by patterns
    code_fragments = []
    i = 0
    while i < len(code):
        matched = False
        for pattern in translation:
            if i + len(pattern) <= len(code) and code[i:i+len(pattern).lower()] == pattern.lower():
                code_fragments.append(pattern)
                i += len(pattern)
                matched = True
                break
        if not matched:
            i += 1

    # Convert to Brainfuck
    bf_code = ''.join(translation.get(fragment, '') for fragment in code_fragments)
    return bf_code

def interpret_bf(code):
    """Interpret Brainfuck code and return the output"""
    code = ''.join(c for c in code if c in '><+-.,[]')
    cells = [0] * 30000
    pointer = 0
    output = []
    i = 0
    bracket_map = {}
    stack = []

    # Pre-compute bracket pairs
    for pos, char in enumerate(code):
        if char == '[':
            stack.append(pos)
        elif char == ']':
            if stack:
                start = stack.pop()
                bracket_map[start] = pos
                bracket_map[pos] = start

    while i < len(code):
        command = code[i]

        if command == '>':
            pointer = (pointer + 1) % 30000
        elif command == '<':
            pointer = (pointer - 1) % 30000
        elif command == '+':
            cells[pointer] = (cells[pointer] + 1) % 256
        elif command == '-':
            cells[pointer] = (cells[pointer] - 1) % 256
        elif command == '.':
            output.append(chr(cells[pointer]))
        elif command == '[' and cells[pointer] == 0:
            i = bracket_map[i]
        elif command == ']' and cells[pointer] != 0:
            i = bracket_map[i]

        i += 1

    return ''.join(output)

if __name__ == "__main__":
    if len(sys.argv) < 3:
        print("Usage: python esolang_decoder.py [language] [file]")
        print("Supported languages: cow, sheep, pig")
        sys.exit(1)

    language = sys.argv[1].lower()
    filename = sys.argv[2]

    try:
        with open(filename, 'r') as f:
            code = f.read()
    except Exception as e:
        print(f"Error reading file: {e}")
        sys.exit(1)

    if language == 'cow':
        bf_code = cow_to_bf(code)
    elif language == 'sheep':
        bf_code = sheep_to_bf(code)
    elif language == 'pig':
        bf_code = pig_to_bf(code)
    else:
        print(f"Unsupported language: {language}")
        sys.exit(1)

    output = interpret_bf(bf_code)
    print(output)

